import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.C1za8uPp.js";const p=JSON.parse('{"title":"Known Limitations","description":"Honest list of what hookshot cannot do and known issues","frontmatter":{"title":"Known Limitations","description":"Honest list of what hookshot cannot do and known issues","audience":["evaluator","operator","architect"]},"headers":[],"relativePath":"project/limitations.md","filePath":"project/limitations.md","lastUpdated":1775245966000}'),i={name:"project/limitations.md"};function n(s,t,d,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h1><p>Honest accounting of what hookshot can&#39;t do, what&#39;s broken, and what to watch out for.</p><h2 id="architectural-limitations" tabindex="-1">Architectural limitations <a class="header-anchor" href="#architectural-limitations" aria-label="Permalink to &quot;Architectural limitations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Limitation</th><th>Impact</th><th>Workaround</th></tr></thead><tbody><tr><td><strong>Matrix room state as database</strong></td><td>No cross-room queries. Can&#39;t list &quot;all connections for org X&quot; without scanning every room.</td><td>Accept this trade-off or build external tooling via <a href="./../reference/provisioning-api">provisioning API</a></td></tr><tr><td><strong>No exactly-once delivery</strong></td><td>Duplicate messages possible after restarts (especially <a href="./../integrations/feeds">feeds</a> without Redis)</td><td>Configure Redis for <a href="./../integrations/feeds#configuration">feed persistence</a>. Accept occasional duplicates for webhooks.</td></tr><tr><td><strong>Single homeserver</strong></td><td>One hookshot instance = one homeserver</td><td>Deploy separate instances per homeserver</td></tr><tr><td><strong>Startup connection scan</strong></td><td>Slow startup with many rooms (scans all rooms, concurrency of 2)</td><td><a href="https://github.com/matrix-org/matrix-hookshot/issues/1088" target="_blank" rel="noreferrer">#1088</a> — startup retry for failed connections</td></tr><tr><td><strong>No webhook signature for generic hooks</strong></td><td>URL secrecy is the only protection</td><td>Treat URLs as secrets, use <a href="./../integrations/generic-webhooks#connection-options">expiration dates</a>, see <a href="./../guides/operator/hardening">hardening</a></td></tr></tbody></table><h2 id="service-specific-limitations" tabindex="-1">Service-specific limitations <a class="header-anchor" href="#service-specific-limitations" aria-label="Permalink to &quot;Service-specific limitations&quot;">​</a></h2><h3 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h3><ul><li>Discussion support requires separate <code>GitHubDiscussionSpace</code> connection — can&#39;t be toggled on a repo connection</li><li>GitHub Enterprise requires explicit <code>enterpriseUrl</code> (no auto-detection)</li><li><a href="https://github.com/matrix-org/matrix-hookshot/issues/1227" target="_blank" rel="noreferrer">Personal notifications doubleposting</a> (known bug)</li></ul><h3 id="gitlab" tabindex="-1">GitLab <a class="header-anchor" href="#gitlab" aria-label="Permalink to &quot;GitLab&quot;">​</a></h3><ul><li>No OAuth flow — each user provides their own personal access token</li><li>GitLab webhook test button sends payloads without <code>action</code> field — test events won&#39;t appear in rooms</li><li>Raw HTTP calls to API v4 (no SDK) — no automatic rate limiting or pagination improvements</li></ul><h3 id="jira" tabindex="-1">JIRA <a class="header-anchor" href="#jira" aria-label="Permalink to &quot;JIRA&quot;">​</a></h3><ul><li><code>jira-client</code> npm package (v8.2.2) is <strong>unmaintained</strong></li><li>JIRA Server reached <strong>EOL February 2024</strong> — Data Center may behave differently</li><li>OAuth 1.0 with RSA-SHA1 for Server is legacy, no token refresh</li><li>Only issue and version events — no boards, sprints, comments</li></ul><h3 id="feeds" tabindex="-1">Feeds <a class="header-anchor" href="#feeds" aria-label="Permalink to &quot;Feeds&quot;">​</a></h3><ul><li><strong>Public feeds only</strong> — no authentication for feed fetching</li><li>Without Redis, <strong>all entries re-post after restart</strong></li><li>Entries arrive in feed order, not sorted by publication date (<a href="https://github.com/matrix-org/matrix-hookshot/issues/1099" target="_blank" rel="noreferrer">#1099</a>)</li><li>No content filtering — all new entries posted</li></ul><h3 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h3><ul><li><code>figma-js</code> package is <strong>unmaintained</strong> (pinned to pre-release v1.16.1-0)</li><li>Only <code>FILE_COMMENT</code> events — no FILE_UPDATE, LIBRARY_PUBLISH</li><li>Requires Figma Professional plan</li></ul><h3 id="generic-webhooks" tabindex="-1">Generic webhooks <a class="header-anchor" href="#generic-webhooks" aria-label="Permalink to &quot;Generic webhooks&quot;">​</a></h3><ul><li><strong>No signature verification</strong> — URL-based security only</li><li><a href="https://github.com/matrix-org/matrix-hookshot/issues/1228" target="_blank" rel="noreferrer">Static webhooks with transformation functions fail</a> due to late QuickJS init (S-Major)</li><li><a href="https://github.com/matrix-org/matrix-hookshot/issues/1251" target="_blank" rel="noreferrer">waitForComplete + transformation returns HTTP error</a></li><li>500ms transformation timeout (hardcoded, not configurable)</li><li>Legacy v1 transformation API still supported — no removal timeline</li></ul><h3 id="openproject" tabindex="-1">OpenProject <a class="header-anchor" href="#openproject" aria-label="Permalink to &quot;OpenProject&quot;">​</a></h3><ul><li>Only work package events — no time entries, meetings, wiki</li><li>Different state event prefix (<code>org.matrix.matrix-hookshot.*</code> vs <code>uk.half-shot.*</code>)</li></ul><h2 id="operational-limitations" tabindex="-1">Operational limitations <a class="header-anchor" href="#operational-limitations" aria-label="Permalink to &quot;Operational limitations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Limitation</th><th>Impact</th><th>Reference</th></tr></thead><tbody><tr><td><a href="./../guides/operator/workers-and-scaling#constraints">Encryption incompatible with workers</a></td><td>Can&#39;t scale encrypted deployments horizontally</td><td>Use single process for E2EE</td></tr><tr><td><a href="https://github.com/matrix-org/matrix-hookshot/issues/1087" target="_blank" rel="noreferrer">Network failures during startup miss connections</a></td><td>Rooms connected during a transient failure are silently skipped</td><td>Restart hookshot after network recovery</td></tr><tr><td><a href="https://github.com/matrix-org/matrix-hookshot/issues/1149" target="_blank" rel="noreferrer">Display names reset on upgrade</a></td><td>Bot display names may revert after redeployment</td><td>Re-set display names manually</td></tr><tr><td>No built-in rate limiting for outbound API calls</td><td>Could hit external service rate limits under heavy use</td><td>Monitor via <a href="./../guides/operator/monitoring">metrics</a></td></tr></tbody></table><h2 id="dependency-risks" tabindex="-1">Dependency risks <a class="header-anchor" href="#dependency-risks" aria-label="Permalink to &quot;Dependency risks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dependency</th><th>Risk</th><th>Status</th></tr></thead><tbody><tr><td><code>jira-client</code> v8.2.2</td><td>Unmaintained</td><td>No replacement planned</td></tr><tr><td><code>figma-js</code> v1.16.1-0</td><td>Unmaintained, pre-release pin</td><td>No replacement planned</td></tr><tr><td><code>matrix-bot-sdk</code> v0.8.0-element.3</td><td>Element-specific fork</td><td>Tied to Element&#39;s release cadence</td></tr><tr><td><code>xml2js</code> (for XML webhooks)</td><td>Has had CVEs historically</td><td>Verify current version</td></tr></tbody></table><h2 id="platform-gaps" tabindex="-1">Platform gaps <a class="header-anchor" href="#platform-gaps" aria-label="Permalink to &quot;Platform gaps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Status</th></tr></thead><tbody><tr><td>Gitea / Forgejo / Codeberg</td><td>Not supported (<a href="https://github.com/matrix-org/matrix-hookshot/issues/304" target="_blank" rel="noreferrer">#304</a> — feature request, no active work)</td></tr><tr><td>Slack</td><td>Not in scope (use <a href="https://github.com/matrix-org/matrix-appservice-slack" target="_blank" rel="noreferrer">matrix-appservice-slack</a>)</td></tr><tr><td>Discord</td><td>Not in scope (use <a href="https://github.com/mautrix/discord" target="_blank" rel="noreferrer">mautrix-discord</a>)</td></tr><tr><td>Linear</td><td>Not supported</td></tr><tr><td>Asana</td><td>Not supported</td></tr><tr><td>Trello</td><td>Not supported</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><strong>Project:</strong> <a href="./roadmap">Roadmap</a> · <a href="./ecosystem">Ecosystem</a></p><p><strong>Architecture:</strong> <a href="./../architecture/failure-and-recovery">Failure and Recovery</a> · <a href="./../architecture/state-and-storage">State and Storage</a></p><p><strong>Operator:</strong> <a href="./../guides/operator/hardening">Hardening</a> · <a href="./../guides/operator/monitoring">Monitoring</a></p><p><strong>Get Started:</strong> <a href="./../get-started/evaluate">Evaluate</a> — Feature comparison</p>',30)])])}const m=e(i,[["render",n]]);export{p as __pageData,m as default};
